def parsear_duracion(s):
    duracion = s.replace('h', '').replace('m', '').replace(':', '')
    if 'h' in duracion:
        horas, minutos = map(int, duracion.split('h'))
    elif 'm' in duracion:
        minutos, horas = map(int, duracion.split('m'))
    else:
        horas = int(duracion.split('h')[0])
        minutos = int(duracion.split('m')[0])
    return horas * 60 + minutos

