def formatear_bytes(n):
    unidades = ['B', 'KB', 'MB', 'GB']
    for i, unidad in enumerate(unidades):
        if n == 0:
            return f'{n} {unidad}'
        valor = n // (1024 ** i)
        if valor == 0:
            valor = 1
            unidad = ''
        else:
            valor *= 1024
            valor = valor / 1024
            if valor >= 1024:
                unidad = f'{valor // 1024:.1f} KB'
                valor = valor % 1024
            elif valor >= 1024 * 1024:
                unidad = f'{valor // (1024 * 1024):.1f} GB'
                valor = valor % (1024 * 1024)
            elif valor >= 1024 * 1024 * 1024:
                unidad = f'{valor // (1024 * 1024 * 1024):.1f} TB'
                valor = valor % (1024 * 1024 * 1024)
        if valor == 0:
            return f'{valor} {unidad}'
    return f'{n} {unidades[i]}'

