def mediana(nums):
    if not nums:
        return None
    nums_ordenadas = sorted(nums)
    n = len(nums_ordenadas)
    if n % 2 == 1:
        return nums_ordenadas[n // 2]
    else:
        return (nums_ordenadas[n // 2 - 1] + nums_ordenadas[n // 2]) / 2

